@@ -55,1 +55,1 @@
-bool VM_Version::_use_zalasr_atomics = false;
+VM_Version::AtomicAccessMode VM_Version::_atomic_access_mode = AtomicAccessMode::RVWMO;
@@ -214,4 +214,10 @@
-  // Latch the native AtomicAccess dispatch flag only after every UseZalasr
-  // adjustment above has settled. See the comment on _use_zalasr_atomics in
-  // vm_version_riscv.hpp.
-  _use_zalasr_atomics = UseZalasr;
+  // Latch the native AtomicAccess dispatch mode only after every UseZalasr and
+  // UseZtso adjustment above has settled. See the comment on
+  // _atomic_access_mode in vm_version_riscv.hpp.
+  if (UseZalasr) {
+    _atomic_access_mode = AtomicAccessMode::RVWMO_ZALASR;
+  } else if (UseZtso) {
+    _atomic_access_mode = AtomicAccessMode::ZTSO;
+  } else {
+    _atomic_access_mode = AtomicAccessMode::RVWMO;
+  }

@@ -298,9 +298,17 @@
-    if (VM_Version::use_zalasr_atomics()) {
-      // Zalasr has no zero-extending form; l{b|h|w}.aq sign-extend. Narrowing
-      // the result back to T discards the extra bits, so both signed and
-      // unsigned T end up with the value the caller expects.
-      return (T)zalasr_load_acquire<byte_size>((const void*)p);
-    } else {
-      T data;
-      __atomic_load(const_cast<T*>(p), &data, __ATOMIC_ACQUIRE);
-      return data;
+    const VM_Version::AtomicAccessMode mode = VM_Version::atomic_access_mode();
+    T data;
+    switch (mode) {
+      case VM_Version::AtomicAccessMode::RVWMO:
+        __atomic_load(const_cast<T*>(p), &data, __ATOMIC_ACQUIRE);
+        break;
+      case VM_Version::AtomicAccessMode::ZTSO:
+        __atomic_load(const_cast<T*>(p), &data, __ATOMIC_RELAXED);
+        compiler_barrier();
+        break;
+      case VM_Version::AtomicAccessMode::RVWMO_ZALASR:
+        // Zalasr has no zero-extending form; l{b|h|w}.aq sign-extend. Narrowing
+        // the result back to T discards the extra bits, so both signed and
+        // unsigned T end up with the value the caller expects.
+        return (T)zalasr_load_acquire<byte_size>((const void*)p);
+      default:
+        ShouldNotReachHere();
@@ -308,0 +316,1 @@
+    return data;
@@ -318,6 +327,16 @@
-    if (VM_Version::use_zalasr_atomics()) {
-      // s{b|h|w|d}.rl stores the low byte_size bytes of the register, so
-      // widening v here is value-preserving for both signed and unsigned T.
-      zalasr_store_release<byte_size>((void*)p, (uint64_t)v);
-    } else {
-      __atomic_store(const_cast<T*>(p), &v, __ATOMIC_RELEASE);
+    const VM_Version::AtomicAccessMode mode = VM_Version::atomic_access_mode();
+    switch (mode) {
+      case VM_Version::AtomicAccessMode::RVWMO:
+        __atomic_store(const_cast<T*>(p), &v, __ATOMIC_RELEASE);
+        break;
+      case VM_Version::AtomicAccessMode::ZTSO:
+        compiler_barrier();
+        __atomic_store(const_cast<T*>(p), &v, __ATOMIC_RELAXED);
+        break;
+      case VM_Version::AtomicAccessMode::RVWMO_ZALASR:
+        // s{b|h|w|d}.rl stores the low byte_size bytes of the register, so
+        // widening v here is value-preserving for both signed and unsigned T.
+        zalasr_store_release<byte_size>((void*)p, (uint64_t)v);
+        break;
+      default:
+        ShouldNotReachHere();
